 function minor(value){if(typeof value==='number'&&!Number.isSafeInteger(value))throw new Error('Dieser Betrag kann hier nicht sicher dargestellt werden. Bitte den Originalbeleg und die Zahlungszuordnung prüfen.');if(!/^-?\d+$/.test(String(value)))throw new Error('Ein bestätigter Geldbetrag fehlt.');return BigInt(value);}
