 function amount(value,positive=true){const raw=String(value).trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(raw))throw new Error('Betrag bitte ohne Tausendertrennzeichen und mit höchstens zwei Nachkommastellen eingeben.');const parts=raw.split('.'),valueMinor=BigInt(parts[0])*100n+BigInt((parts[1]||'').padEnd(2,'0'));if(positive&&valueMinor<=0n)throw new Error('Der Zahlungsbetrag muss größer als null sein.');if(valueMinor>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('Der Betrag ist zu groß für eine sichere Eingabe in dieser Ansicht.');return Number(valueMinor);}
