 function docLabel(value){return {READY:'PDF lokal fertig und geprüft',PDF_PENDING:'Beleg ausgestellt · PDF ausstehend',PENDING:'PDF ausstehend',RUNNING:'PDF wird lokal erstellt',ERROR:'PDF-Erstellung benötigt Prüfung',MISSING:'Original-PDF noch nicht lokal bestätigt',ORIGINAL_REVIEW_REQUIRED:'Original-PDF muss geprüft oder aus einem belegten Original zugeordnet werden'}[value]||'PDF-Status prüfen';}
