 function savedDraft(){const raw=HGDraftStorage.getItem(KEY);if(raw===null)return null;try{const draft=JSON.parse(raw);if(draft?.formatVersion!==1||typeof draft.request_id!=='string'||!draft.request_id)throw Error();return draft;}catch(_){throw Error('Der erhaltene Zahlungsentwurf ist nicht lesbar. Diesen Vorgang zuerst prüfen; keine neue Zahlungsaktion darüber speichern.');}}
