 function refreshOpenInvoice(id){if(!id)return;const button=document.querySelector('[data-invoice-payment="'+CSS.escape(id)+'"]');if(button?.closest('dialog[open]')&&typeof window.openInvoiceRecord==='function')window.openInvoiceRecord(id);}
