 function history(data,invoiceId){const entries=data.payments||[],reversed=new Set(entries.map(row=>row.reverses).filter(Boolean)),withdrawn=new Set(entries.filter(row=>row.corrects&&minor(row.amount_minor)===0n).map(row=>row.corrects));return '<section><h3>Zahlungsverlauf</h3>'+(entries.length?'<ul class="local-payment-history">'+entries.map(payment=>'<li><strong>'+E(payment.reversal?'Rückbuchung':payment.corrects&&minor(payment.amount_minor)===0n?'Vollständige Rücknahme':payment.corrects?'Korrekturbuchung':'Zahlung')+' · '+E(money(payment.amount_minor))+'</strong><p>'+E([payment.paid_on||'',methodLabels[payment.method]||'',payment.reference||''].filter(Boolean).join(' · '))+'</p>'+(payment.reason?'<p>Grund: '+E(payment.reason)+'</p>':'')+'<p>'+E((payment.allocations||[]).map(row=>invoiceLabel(row.invoice_id)+': '+money(row.amount_minor)).join('; ')||'Keine Rechnung zugeordnet')+'</p>'+(minor(payment.unallocated_minor||0)>0n?'<p>Nicht zugeordnetes Guthaben: '+E(money(payment.unallocated_minor))+'</p>':'')+(payment.reversal||minor(payment.amount_minor)===0n?'':reversed.has(payment.payment_id)?'<p>'+E(withdrawn.has(payment.payment_id)?'Diese Zahlungsaufzeichnung wurde vollständig zurückgenommen.':'Durch eine nachvollziehbare Korrektur berichtigt.')+'</p>':button('Zahlung korrigieren','data-local-correct="'+E(payment.payment_id)+'"'))+'</li>').join('')+'</ul>':'<p>Noch keine Zahlung in diesem lokalen Ledger erfasst. Historische Bezahlmarkierungen werden nicht als erfundene Zahlungen übernommen.</p>')+(data.total>entries.length?button('Weitere Zahlungen laden','data-local-history-more data-offset="'+entries.length+'" data-invoice="'+E(invoiceId||'')+'"'):'')+'</section>';}
 function balanceView(balance){const known=balance.balance_known!==false&&balance.remaining_minor!==null;return '<section class="local-payment-context"><h3>'+E(invoiceLabel(balance.invoice_id))+'</h3><p>Rechnungsbetrag: '+E(money(balance.invoice_minor))+'</p>'+(known?'<p class="local-invoice-status-chip">'+E(balance.paid?'Bezahlt':'Restbetrag: '+money(balance.remaining_minor))+'</p>'+(minor(balance.credit_minor||0)>0n?'<p>Guthaben / Überzahlung: '+E(money(balance.credit_minor))+'</p>':''):'<p class="local-payment-warning">Historische Markierung: '+E(balance.legacy_status||'nicht eindeutig')+'. Der tatsächliche Restbetrag ist nicht belegt und muss vor einer neuen Zuordnung abgeglichen werden.</p>')+'</section>';}
