 function serverIssueReview(envelope,id){const review=envelope.issue_review,snapshot=review?.snapshot,object=value=>value&&typeof value==='object'&&!Array.isArray(value);if(review?.formatVersion!==1||review.invoice_id!==id||!/^[0-9a-f]{64}$/.test(review.record_hash||'')||!/^[0-9a-f]{64}$/.test(review.context_hash||'')||envelope.record_hash!==review.record_hash||typeof review.ready!=='boolean'||!Array.isArray(review.blockers)||!object(snapshot)||snapshot.invoice?.id!==id||!(object(snapshot.issuer)||review.ready===false&&snapshot.issuer===null)||!(object(snapshot.recipient)||review.ready===false&&snapshot.recipient===null)||review.ready===true&&review.blockers.length!==0||!object(snapshot.authority)||!['worklogs','materials','orders'].every(key=>Array.isArray(snapshot[key])))throw new Error('Der verbindliche lokale Prüfstand ist unvollständig. Bitte erneut lesen; es wird keine Rechnung aus ungeprüften Angaben ausgestellt.');return clone(review);}
