 function sameReview(left,right){return left?.record_hash===right?.record_hash&&left?.context_hash===right?.context_hash&&left?.ready===right?.ready&&JSON.stringify(left?.blockers||[])===JSON.stringify(right?.blockers||[]);}
 function issuePending(){const raw=HGDraftStorage.getItem(issueKey);if(!raw)return null;let value;try{value=JSON.parse(raw);}catch(_){throw new Error('Die erhaltene Ausgabeaktion ist nicht lesbar. Zuerst den gespeicherten Belegstand prüfen; keine neue Ausgabeaktion anlegen.');}if(!value?.args?.invoice_id||!value.args.request_id)throw new Error('Die erhaltene Ausgabeaktion ist unvollständig. Bitte den Belegstand prüfen.');return value;}
