 function reviewLedger(){const draft=active.draft;if(draft.frozen){reconcilePending();return;}updateDraft();try{const next=ledger('');const lines=draft.allocations.map(row=>{const before=active.data.balances.find(b=>b.invoice_id===row.invoice_id),after=next.balances.find(b=>b.invoice_id===row.invoice_id);return invoiceLabel(row.invoice_id)+': bisher '+money(before?.remaining_minor)+', aktuell '+money(after?.remaining_minor);});if(!confirm('Aktuellen Zahlungsstand prüfen:\n'+lines.join('\n')+'\nDie Eingabe bleibt erhalten. Diesen Vergleichsstand übernehmen und anschließend ausdrücklich buchen?'))return;active.data=next;draft.ledger_hash=next.ledger_hash;draft.request_id=request();draft.confirmed=false;draft.withdrawal_confirmed=false;draft.refused=false;retain();drawPayment();$('local-payment-state').textContent='Aktueller Stand ausdrücklich übernommen. Betrag und Zuordnungen erneut bestätigen.';}catch(error){$('local-payment-form').querySelector('[role=alert]').textContent=feedback(error);}}
 function reconcilePending(){const draft=active.draft;if(!draft.frozen)return;try{let data=ledger(''),entries=data.payments.slice(),offset=entries.length;while(offset<data.total){const more=native('get_payment_ledger',{offset,limit:100});entries=entries.concat(more.payments||[]);if(!more.payments?.length)break;offset+=more.payments.length;}const payment=entries.find(row=>row.client_request_id===draft.frozen.args.request_id);if(!payment){$('local-payment-form').querySelector('[role=alert]').textContent=draft.restore_review_required?'Das ursprüngliche Zahlungsergebnis ist nach der Wiederherstellung nicht vollständig belegt. Keine alte Buchung erneut ausführen. Eingaben bleiben erhalten; den aktuellen Zahlungsstand und Originalnachweise prüfen.':'Noch kein eindeutiger gespeicherter Eingang für diese Aktion gefunden. „Dieselbe Buchung erneut prüfen“ verwendet dieselbe Aktionskennung und erzeugt bei Wiederholung keinen zweiten Eingang.';return;}const expected=draft.frozen.args,allocationSet=rows=>JSON.stringify((rows||[]).map(row=>({invoice_id:row.invoice_id,amount_minor:String(row.amount_minor)})).sort((a,b)=>a.invoice_id.localeCompare(b.invoice_id)));if(String(payment.amount_minor)!==String(expected.amount_minor)||payment.paid_on!==expected.paid_on||payment.method!==expected.method||(payment.reference||'')!==(expected.reference||'')||(payment.corrects||'')!==(expected.payment_id||'')||allocationSet(payment.allocations)!==allocationSet(expected.allocations))throw new Error('Die gefundene Aktion enthält andere Angaben. Keine weitere Zahlung buchen; Verlauf und Aktionsbeleg prüfen.');draft.restore_review_required=false;showCommittedPayment(draft,{payment_id:payment.payment_id});}catch(error){$('local-payment-form').querySelector('[role=alert]').textContent=feedback(error);}}
 function bindHistory(node){node.querySelectorAll('[data-local-correct]').forEach(button=>button.onclick=()=>openPayment(active.invoiceId,button.dataset.localCorrect));node.querySelector('[data-local-history-more]')?.addEventListener('click',event=>{try{const button=event.currentTarget,id=button.dataset.invoice,more=native('get_payment_ledger',{...(id?{invoice_id:id}:{}),offset:Number(button.dataset.offset),limit:100});active.data.payments=active.data.payments.concat(more.payments||[]);active.data.total=more.total;const parent=button.closest('section');parent.outerHTML=history(active.data,id);bindHistory(node);}catch(error){window.showUndoToast?.(feedback(error));}});}
 function documentStatus(host,id){if(host.querySelector('[data-local-document="'+CSS.escape(id)+'"]'))return;const section=document.createElement('section');section.className='local-document-status';section.dataset.localDocument=id;host.prepend(section);let retry=null;const render=()=>{try{const data=native('get_invoice_document_job',{invoice_id:id}),originalReview=data.original_review_required===true||data.job?.original_review_required===true||data.pdf_state==='ORIGINAL_REVIEW_REQUIRED',proof=/^[0-9a-f]{64}$/.test(data.job?.snapshot_sha256||'')?data.job.snapshot_sha256:'';section.innerHTML='<p><strong>'+E(docLabel(originalReview?'ORIGINAL_REVIEW_REQUIRED':data.pdf_state))+'</strong></p>'+(proof?'<label>Prüfkennung des eingefrorenen Belegs<input readonly data-local-document-proof aria-label="Prüfkennung des eingefrorenen Belegs" value="'+E(proof)+'"></label>':'')+(originalReview?'<p>Originalprüfung im bestehenden Belegabgleich fortsetzen. Ein unbekannter Altbeleg wird nicht neu erzeugt.</p>':'')+'<p>Belegstatus und PDF-Status werden getrennt geführt. Teilen ist keine Versand- oder Zustellbestätigung.</p><div class="local-payment-actions">'+button('PDF-Status lesen','data-local-document-read')+(data.pdf_state==='READY'&&!originalReview?button('Geprüftes Original-PDF teilen','data-local-document-share'):originalReview?'':button('Lokale PDF-Erstellung erneut anfordern','data-local-document-retry'))+'</div><p role="status" data-document-feedback></p><p role="alert"></p>';section.querySelector('[data-local-document-read]').onclick=render;section.querySelector('[data-local-document-retry]')?.addEventListener('click',()=>{try{if(!retry)retry={request_id:request(),invoice_id:id,expected_record_hash:data.record_hash};native('retry_invoice_document_job',retry);retry=null;render();}catch(error){section.querySelector('[role=alert]').textContent=feedback(error);}});section.querySelector('[data-local-document-share]')?.addEventListener('click',()=>{try{native('prepare_invoice_share',{request_id:request(),invoice_id:id,channel:'share'});const result=AndroidData.shareInvoiceById(id,'share');if(String(result).startsWith('ERROR:'))throw new Error(String(result).slice(6));section.querySelector('[data-document-feedback]').textContent='An die Geräteauswahl übergeben. Versand und Zustellung sind nicht bestätigt.';}catch(error){section.querySelector('[role=alert]').textContent=feedback(error);}});}catch(error){section.innerHTML='<p role="alert">'+E(feedback(error))+'</p>'+button('PDF-Status erneut lesen','data-local-document-read');section.querySelector('[data-local-document-read]').onclick=render;}};render();}
 function scan(){observerQueued=false;if(!ever&&capability!==true)return;document.querySelectorAll('[data-invoice-payment]').forEach(button=>{const id=button.dataset.invoicePayment;if(!id)return;documentStatus(button.parentElement,id);});}
